"""OP-xx.layout.json of the v0.1.0 zero-tail (stack) layout for the electronics agent. TEST PROJECT, water only."""
from __future__ import annotations

SCHEMA_S = "openpatch-v010-layout/2"


def layout_json(p: dict, L: dict, G: dict) -> dict:
    S = p["v010"]["stack"]
    X0, V0 = G["X0"], G["V0"]
    xr, B, pl = L["x_r1"], L["bench"], G["plan"]
    z0, ztop = G["z0"], G["ztop"]
    top_free = G["zi"] - ztop

    def bf(x, y):
        return [round(x - X0, 3), round(y - V0, 3)]

    def rb(x0, y0, x1, y1):
        return [round(x0 - X0, 3), round(y0 - V0, 3), round(x1 - X0, 3), round(y1 - V0, 3)]

    c, u, sh = G["cell"], G["usb"], G["shelf"]
    yc = p["dock"]["y_c"]
    zones = [
        {"id": "dock_tunnel", "rect_board": rb(xr + 4.4, yc - 6.2, L["x_end"], yc + 6.2), "top_max_mm": round(top_free - 0.2, 2), "bottom_max_mm": 0.0,
         "note": "over the dock insert (top z 5.2) and the Insight Flex dome path (z 5.0): top-side parts only; ONLY the dock hall may hang below (0.4 mm)"},
        {"id": "cell_strip", "rect_board": rb(c["x"][0], c["y"][0], c["x"][1], c["y"][1]), "top_max_mm": round(top_free - 0.2, 2), "bottom_max_mm": 0.75,
         "note": "cell top z %.2f: only the two SMD spring contacts (pads on the cell) below the board" % c["z"][1]},
        {"id": "usb_zone", "rect_board": rb(u["board"]["x"][0] - 0.5, u["y"][0] - 1.0, xr + pl["tail_len"], u["y"][1] + 1.0), "top_max_mm": round(top_free - 0.2, 2), "bottom_max_mm": 0.0,
         "note": "USB-C receptacle (z %.2f..%.2f) + USB board (z %.2f..%.2f) below; the main board above is free on its top side, only the 2 link contacts reach down" % (u["z"][0], u["z"][1], u["board"]["z"][0], u["board"]["z"][1])},
        {"id": "wing_spindle", "rect_board": rb(X0, S["board"]["left_y0"], xr + S["board"]["full_from_u"], S["board"]["y1"]), "top_max_mm": round(top_free - 0.2, 2), "bottom_max_mm": 1.5,
         "note": "TMAG5273 hangs 1.45 mm on the spindle axis; DRV5032 pair on top"},
        {"id": "motor_tongue", "rect_board": rb(G["tongue_x0"], S["board"]["tongue_y0"], X0, S["board"]["y1"]), "top_max_mm": round(top_free - 0.2, 2), "bottom_max_mm": round(G["mspring_gap"], 2),
         "note": "4 SMD spring contacts (pitch %.1f) press on the FPC pads of the contact shelf (pad top z %.2f)" % (S["motor"]["pitch"], G["motor_pads"][0]["z_top"])},
    ]
    sens = [{"id": sn["id"], "part": sn["part"], "side": sn["side"], "center_board_mm": bf(*sn["center_pod_mm"]), "body_xyz_mm": sn["body_xyz_mm"], "z_body_pod": sn["z_body_pod"],
             "note": "unchanged relative to the spindle magnet / dock interface (u = %.2f)" % (sn["center_pod_mm"][0] - xr)} for sn in B["sensors"]]
    return {
        "schema": SCHEMA_S, "variant": L["variant"], "kind": "integrated_pod_board", "layout": "stack (spec 2b/2d: board over the dock tunnel, USB-C, no charge pads)", "units": "mm",
        "status": "generated by mechanical/generate.py --variant v010; CAD-verified by check.py --variant v010", "warning": "TEST PROJECT - never worn, water only.",
        "frames": {"pod": "X length, Y width, Z up (Z=0 skin side)", "board": "bx,by = pod x,y minus transform.board_origin_in_pod_mm, viewed from the TOP (lid side), X right, Y up; KiCad: flip Y",
                   "layers": "F.Cu = top/lid side (+Z), B.Cu = bottom/floor side (-Z)"},
        "pod": {"length": round(L["length"], 3), "width": L["width"], "height": L["height"], "x_r1": round(xr, 4), "x_end_inner": round(L["x_end"], 3)},
        "transform": {"board_origin_in_pod_mm": [round(X0, 4), round(V0, 4)], "rotation_deg": 0, "mirror": False, "board_bottom_z_pod": z0, "board_top_z_pod": round(ztop, 3)},
        "boards": {"MAIN": {"outline_polygon_board_mm": G["outline_board"], "thickness_mm": S["board"]["t"], "layers": 4, "z_pod": [z0, round(ztop, 3)], "source": G["electronics_file"] or "mechanical generator (stack layout)",
                            "note": "tongue (motor contacts) + wing (spindle sensors) + full width over the dock tunnel; holes below are NPTH. May be split by the electronics agent."},
                   "USB": {"rect_board_mm": rb(u["board"]["x"][0], u["board"]["y"][0], u["board"]["x"][1], u["board"]["y"][1]), "z_pod": u["board"]["z"], "thickness_mm": S["usb"]["board_t"],
                           "link_to_main": "2 elastomer (zebra) / pogo links %.1f mm tall, z %.2f..%.2f (no soldering); VERIFY the part" % (S["usb"]["link_h"], u["link_z"][0], u["link_z"][1])}},
        "stack_z_pod": {"floor_top": L["wall"], "cell": c["z"], "cell_pad_top": round(c["z"][1] + 0.05, 3), "board_bottom": z0, "board_top": round(ztop, 3), "lid_inner": round(G["zi"], 3), "top_free_mm": round(top_free, 2),
                        "spring_contact_gap_mm": G["spring_gap"], "motor_spring_gap_mm": G["mspring_gap"], "spring_free_height_max_mm": S["cell"]["spring_free_max"]},
        "zones": zones,
        "heights_mm": {"top_max": round(top_free - 0.2, 2), "bottom_over_dock_tunnel": 0.0, "bottom_over_dock_hall_only": 0.4, "bottom_over_battery": 0.75, "bottom_over_motor_tongue": round(G["mspring_gap"], 2)},
        "battery": {"class": S["cell"]["class"], "envelope_mm": [S["cell"]["l"], S["cell"]["w"], S["cell"]["t"]], "bay_rect_board": rb(c["x"][0], c["y"][0], c["x"][1], c["y"][1]),
                    "spring_contacts": {"centers_board_mm": [bf(*q["center_pod"]) for q in G["cell_pads"]], "footprint_mm": S["cell"]["spring"], "free_height_max_mm": S["cell"]["spring_free_max"], "compressed_mm": G["spring_gap"]}},
        "motor_contacts": {"scheme": "NFP motor with FPC tail (spec 1c, custom/group buy) lying in the floor groove, bent up at the shelf edge, pads on the shelf; 4 SMD spring contacts on the main board tongue",
                           "pad_centers_board_mm": [bf(*q["center_pod"]) for q in G["motor_pads"]], "pad_top_z_pod": G["motor_pads"][0]["z_top"], "pitch_mm": S["motor"]["pitch"], "spring_footprint_mm": S["motor"]["spring"],
                           "shelf_pod_x": sh["x"], "shelf_pod_y": sh["y"], "note": "pin order along Y as nfp_term.pin_order_drawing_left_to_right in OP-xx.mech.json"},
        "radio": {"part": S["radio"]["part"], "side": "top", "rect_board_mm": rb(G["radio"]["x"][0], G["radio"]["y"][0], G["radio"]["x"][1], G["radio"]["y"][1]), "height_mm": S["radio"]["h"], "antenna_end": "+X",
                  "note": "over the dock tunnel: no metal below except the dock magnet and the dock hall"},
        "usb_c": {"part": S["usb"]["part"], "mount": "mid-mount on the USB board, nose through the +X end wall opening", "receptacle_board_mm": rb(u["x"][0], u["y"][0], u["x"][1], u["y"][1]), "z_pod": u["z"],
                  "wall_opening_board_mm": rb(u["open_x"][0], u["open_y"][0], u["open_x"][1], u["open_y"][1]), "wall_opening_z_pod": u["open_z"],
                  "gasket": "silicone frame %.1f mm thick, %.1f mm wide around the opening, inside the end wall" % (S["usb"]["gasket_t"], S["usb"]["gasket_w"]),
                  "web_above_opening_mm": u["web_above_mm"], "note": "IPX7 needs the receptacle's own front seal + the gasket; vendor drawing VERIFY"},
        "piezo": {"side": "top", "rect_board_mm": rb(G["piezo"]["x"][0], G["piezo"]["y"][0], G["piezo"]["x"][1], G["piezo"]["y"][1]), "height_mm": S["piezo"]["h"], "sound_port_board_mm": bf(*G["piezo"]["port"])},
        "button": {"side": "top", "center_board_mm": bf(*G["switch"]["center_pod"]), "size_mm": G["switch"]["size"], "membrane_d_mm": p["button"]["d_memb"]},
        "vent": {"center_board_mm": bf(*G["vent"]["center_pod"]), "hole_d_mm": G["vent"]["hole_d"], "recess_d_mm": G["vent"]["recess_d"]},
        "hall_sensors": sens,
        "holes_npth": [dict(what=h["what"], center_board_mm=bf(*h["center_pod"]), d_mm=h["d"]) for h in G["holes"]],
        "mounting": {"posts_under_board": [dict(center_board_mm=bf(xr + q[0], q[1]), d_mm=p["bench"]["mount"]["post_d"]) for q in p["bench"]["mount"]["posts"]]
                     + [dict(center_board_mm=bf(xr + q[0], q[1]), d_mm=p["bench"]["mount"]["pin_post_d"], note="locating pin post") for q in p["bench"]["mount"]["pins"]],
                     "lid_hold_down_pads_top": [dict(center_board_mm=bf(xr + q[0], q[1]), d_mm=p["bench"]["mount"]["hd_d"], top_keepout_d_mm=p["bench"]["mount"]["hd_d"] + 0.6) for q in p["bench"]["mount"]["hd"]]},
    }
